///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnExcelDown
 * @description fn Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnExcelDown = async function () {
    try { return await $c.data.downFile("/down/excel.do?method=searchDownloadInvestExcel", "", ($c.util.getComponent("dma_fnExcelDownReq") ? $c.util.getComponent("dma_fnExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name fnCheckAllEvent
 * @description fn Check All Event 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllEvent = function () {
    const form = $("form[name=JLDINF26500]");
    const allChk = $("input[name=ipt_all]").is(":checked");
    if (allChk) {
        $("input[name=ch]", form).attr("checked", "checked");
    } else {
        $("input[name=ch]", form).removeAttr("checked");
    }
};

/**
 * @method
 * @name fnCheckEvent
 * @description fn Check Event 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckEvent = function () {
    const form = $("form[name=JLDINF26500]");
    const len = $("input[name=ch]:checked").length;
    if (len === 2) {
        $("input[name=ipt_all]", form).attr("checked", "checked");
    } else {
        $("input[name=ipt_all]", form).removeAttr("checked");
    }
};

/**
 * @method
 * @name open_corp_cd
 * @description open corp cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_corp_cd = function () {
    formName = (document.JLDINF26500 || { elements: [] });
    fn_popupCorpSearch(formName);
};

/**
 * @method
 * @name toggle
 * @description toggle 처리
 * @returns {void}
 * @hidden N
 */
scwin.toggle = function () {
    $("#searchTb").toggle();
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function (idx) {
    let form = $("form[name=JLDINF26500]");
    if ($c.util.getComponent('cal_startDD').getValue() > $c.util.getComponent('cal_endDD').getValue()) {
        await $c.win.alert("종료일은 시작일 이후 날짜로 입력하세요");
        frm.endDate.value = "";
        return;
    }
    form = $("form[name=JLDINF26500]");
    const items = $("input[name=ch]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_ckKey').setValue(items);
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    const url = "/down/downList.do?method=investDownList";
    const fm = (document.JLDINF26500 || { elements: [] });
    fm.action = url;
    fm.target = "_self";
    await $c.data.downFile(url, "", {});
};

/**
 * @method
 * @name fnDownloadChk
 * @description fn Download Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownloadChk = async function () {
    const form = (document.JLDINF26500 || { elements: [] });
    fn_downInfoWin(form);
    await $c.win.alert("조회 내용이 없습니다.");
};

/**
 * @method
 * @name fnExcelDown
 * @description fn Excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnExcelDown = async function () {
    const items = $("input[name=ch]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_ckKey').setValue(items);
    scwin.fm = (document.JLDINF26500 || { elements: [] });
    scwin.fm.method = 'post';
    scwin.fm.action = '/down/excel.do?method=searchDownloadInvestExcel';
    scwin.fm.target = "iframeExcel";
    await scwin.tx_fnExcelDown();
};

/**
 * @method
 * @name krxpage_pagenavigator_122_onclick
 * @description krxpage_pagenavigator_122 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_122_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; await scwin.goSearch(index); };
